const updateTitle = `-- name: UpdateTitle :one
update library_titles set title = $3, subtitle = $4, author = $5, publisher = $6, publish_year = $7,
  isbn = $8, classification = $9, language = $10, cover_asset_id = $11
where tenant_id = $1 and id = $2 and deleted_at is null
returning id, tenant_id, title, subtitle, author, publisher, publish_year, isbn, classification, language, cover_asset_id, created_at, updated_at, deleted_at, is_opac, search_vector
`

type UpdateTitleParams struct {
	TenantID       uuid.UUID   `json:"tenant_id"`
	ID             uuid.UUID   `json:"id"`
	Title          string      `json:"title"`
	Subtitle       string      `json:"subtitle"`
	Author         string      `json:"author"`
	Publisher      string      `json:"publisher"`
	PublishYear    pgtype.Int4 `json:"publish_year"`
	Isbn           string      `json:"isbn"`
	Classification string      `json:"classification"`
	Language       string      `json:"language"`
	CoverAssetID   pgtype.UUID `json:"cover_asset_id"`
}

func (q *Queries) UpdateTitle(ctx context.Context, arg UpdateTitleParams) (LibraryTitle, error) {
	row := q.db.QueryRow(ctx, updateTitle,
		arg.TenantID,
		arg.ID,
		arg.Title,
		arg.Subtitle,
		arg.Author,
		arg.Publisher,
		arg.PublishYear,
		arg.Isbn,
		arg.Classification,
		arg.Language,
		arg.CoverAssetID,
	)
	var i LibraryTitle
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.Title,
		&i.Subtitle,
		&i.Author,
		&i.Publisher,
		&i.PublishYear,
		&i.Isbn,
		&i.Classification,
		&i.Language,
		&i.CoverAssetID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.IsOpac,
		&i.SearchVector,
	)
	return i, err
}
